package com.justjava.humanresource.employeeexit.service;
import com.justjava.humanresource.core.enums.PayrollRunStatus; import com.justjava.humanresource.employeeexit.dto.*; import com.justjava.humanresource.employeeexit.entity.*; import com.justjava.humanresource.employeeexit.enums.*; import com.justjava.humanresource.employeeexit.repository.*; import com.justjava.humanresource.hr.repository.EmployeeRepository; import com.justjava.humanresource.payroll.entity.*; import com.justjava.humanresource.payroll.enums.*; import com.justjava.humanresource.payroll.repositories.*; import lombok.RequiredArgsConstructor; import org.springframework.beans.BeanUtils; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.time.LocalDateTime; import java.util.*;
@Service @RequiredArgsConstructor public class ExitPayrollImpactService {
 private final ExitSettlementRepository settlements;private final ExitSettlementLineRepository settlementLines;private final ExitSettlementPayrollPostingRepository postings;private final ExitSettlementPayrollLineMappingRepository mappings;private final EmployeeExitCaseRepository exits;private final EmployeeRepository employees;private final PayrollPeriodRepository periods;private final PayrollRunRepository runs;private final PayrollLineItemRepository payrollLines;private final EmployeeExitActivityService activity;
 @Transactional(readOnly=true)public ExitPayrollImpactPreview preview(Long settlementId){ExitSettlement s=requireApproved(settlementId);var x=exits.findById(s.getExitCaseId()).orElseThrow();List<ExitPayrollImpactLine> ls=settlementLines.findBySettlementIdOrderById(s.getId()).stream().map(l->new ExitPayrollImpactLine(l.getId(),code(l),l.getDescription(),l.isEarning()?PayComponentType.EARNING:PayComponentType.DEDUCTION,l.getAmount(),l.isTaxable())).toList();return new ExitPayrollImpactPreview(s.getId(),x.getEmployeeId(),s.getGrossEarnings(),s.getTotalDeductions(),s.getNetSettlement(),ls);}
 @Transactional public ExitSettlementPayrollPosting postApprovedSettlement(Long settlementId,Long periodId,Long actor){ExitSettlement s=requireApproved(settlementId);String key="EXIT-"+s.getExitCaseId()+"-SETTLEMENT-"+s.getSettlementVersion()+"-"+s.getCalculationFingerprint();var existing=postings.findByPostingKey(key);if(existing.isPresent())return existing.get();var x=exits.findById(s.getExitCaseId()).orElseThrow();PayrollPeriod period=periods.findById(periodId).orElseThrow(()->new IllegalArgumentException("Payroll period not found."));if(!period.getCompanyId().equals(x.getCompanyId()))throw new IllegalStateException("Payroll period belongs to a different company.");PayrollRun base=runs.findLatestPostedRunForEmployeeAndPeriod(x.getEmployeeId(),period.getPeriodStart(),period.getPeriodEnd()).orElseThrow(()->new IllegalStateException("A posted payroll run is required before exit settlement posting."));PayrollRun amendment=new PayrollRun();BeanUtils.copyProperties(base,amendment,"id","createdAt","updatedAt","version");amendment.setParentRun(base);amendment.setRunType(PayrollRunType.AMENDMENT);amendment.setVersionNumber(Optional.ofNullable(runs.findMaxVersionForEmployeeAndPeriod(x.getEmployeeId(),period.getPeriodStart(),period.getPeriodEnd())).orElse(base.getVersionNumber())+1);amendment.setAmendmentReason("Employee exit settlement "+s.getId());PayrollRun saved=runs.saveAndFlush(amendment);for(PayrollLineItem old:payrollLines.findByPayrollRunId(base.getId()))payrollLines.save(copy(old,saved));ExitSettlementPayrollPosting p=new ExitSettlementPayrollPosting();p.setExitCaseId(x.getId());p.setSettlementId(s.getId());p.setPayrollRunId(saved.getId());p.setPayrollPeriodId(periodId);p.setPostingKey(key);p.setPostedByEmployeeId(actor);p.setPostedAt(LocalDateTime.now());p=postings.saveAndFlush(p);for(ExitSettlementLine line:settlementLines.findBySettlementIdOrderById(s.getId())){PayrollLineItem li=new PayrollLineItem();li.setPayrollRun(saved);li.setEmployee(employees.findById(x.getEmployeeId()).orElseThrow());li.setComponentType(line.isEarning()?PayComponentType.EARNING:PayComponentType.DEDUCTION);li.setComponentCode(code(line));li.setDescription(line.getDescription());li.setAmount(line.getAmount());li.setTaxable(line.isTaxable());li.setPensionable(false);li.setPartOfGross(line.isEarning());li=payrollLines.save(li);ExitSettlementPayrollLineMapping map=new ExitSettlementPayrollLineMapping();map.setPostingId(p.getId());map.setSettlementLineId(line.getId());map.setPayrollLineItemId(li.getId());map.setSourceReference("EXIT_SETTLEMENT_LINE_"+line.getId());mappings.save(map);}saved.setGrossPay(base.getGrossPay().add(s.getGrossEarnings()));saved.setTotalDeductions(base.getTotalDeductions().add(s.getTotalDeductions()));saved.setNetPay(base.getNetPay().add(s.getNetSettlement()));runs.save(saved);s.setStatus(SettlementStatus.POSTED);s.setPayrollRunId(saved.getId());settlements.save(s);activity.record(x.getId(),"SETTLEMENT_POSTED","Settlement posted to payroll run "+saved.getId(),actor,null);return p;}
 private ExitSettlement requireApproved(Long id){ExitSettlement s=settlements.findById(id).orElseThrow(()->new IllegalArgumentException("Settlement not found."));if(s.getStatus()!=SettlementStatus.APPROVED&&s.getStatus()!=SettlementStatus.POSTED)throw new IllegalStateException("Only an approved settlement can be posted.");return s;}
 private String code(ExitSettlementLine l){return "EXIT_"+l.getLineType().name();}private PayrollLineItem copy(PayrollLineItem old,PayrollRun run){PayrollLineItem n=new PayrollLineItem();BeanUtils.copyProperties(old,n,"id","createdAt","updatedAt","version","payrollRun");n.setPayrollRun(run);return n;}}
